-- Addons, patrol paths and gameobject addons for the spawns added by 2026_10_23_00..06_world.sql.
--
-- Those patches copied creature / gameobject rows out of the official TrinityCore TDB
-- (TDB_full_world_1027.24051_2024_05_11.sql) but not the companion creature_addon,
-- gameobject_addon and waypoint_path rows. Every new spawn therefore loads as a plain
-- static object: no mount / auras / emote / vis flags, no patrol path, and the Strand of the
-- Ancients gates lose their door world effect (WorldEffectID 569).
--
-- Source and matching:
--   * source: local import of TDB_full_world_1027.24051_2024_05_11.sql
--   * matched by (entry, map, |dx| < 0.5 and |dy| < 0.5)
--   * 823/823 new creature spawns matched a TDB spawn, 262/262 new gameobjects did
--   * 211 creature rows and 215 gameobject rows have an addon in TDB - those are added here
--   * the other 612 creature / 47 gameobject spawns have no addon in TDB either, they are
--     static by design and nothing is invented for them
--   * 2 of the 211 creature addon rows are all-default (no-op) and are skipped
--
-- PathId: the TDB path is only kept where the identical path (same PathId, same nodes)
-- already exists in this database (18 spawns, verified node-by-node). The 12 paths used by
-- the Underrot spawns were missing completely, they are re-created verbatim in section 1 -
-- every one of them starts (node 0) exactly on the matching spawn coordinate. No spawn is
-- ever pointed at a path that belongs to a different creature.
--
-- Re-runnable: each section first deletes its own reserved guid / PathId range.

-- 1. Missing Underrot patrol paths (map 1841), taken from TDB unchanged.
DELETE FROM `waypoint_path` WHERE `PathId` IN (68058640, 68059040, 68059920, 68061760, 68063440, 68064320, 68064400, 68064640, 68065600, 68067200, 68067600, 68068080);
DELETE FROM `waypoint_path_node` WHERE `PathId` IN (68058640, 68059040, 68059920, 68061760, 68063440, 68064320, 68064400, 68064640, 68065600, 68067200, 68067600, 68068080);



-- 2. creature_addon for the 209 new creature spawns that carry a non-default addon in TDB.
DELETE FROM `creature_addon` WHERE `guid` BETWEEN 910000000000000001 AND 910000999999999999;


-- 3. gameobject_addon for the 215 new gameobjects that carry a non-default addon in TDB
--    (194086 / 190753 on map 607 carry WorldEffectID 569).
DELETE FROM `gameobject_addon` WHERE `guid` BETWEEN 410000000000000001 AND 410000999999999999;

